TOK = re.compile(r'(?<![\w.^/])([-+\u2212]?\d+\.\d+)(?![\d.]|e-?\d)|2\^\(?([-+]?\d+(?:\.\d+)?)')
MEMLEFT = re.compile(r'(rows|store|entries|memory|columns|matrix|macaulay|mr_[bm]|w\(\d+, ?\d+\)|storage|stores)[^.;]{0,25}$', re.I)
TIMECTX = re.compile(r'(bit|cost|margin|log2 ?c|time|c_i|runner|gap|anchor|operation|below|above|exceed|spread|move|lies|c_b|c_m|\bmu|m\*|stage)', re.I)
RHOCTX = re.compile(r'(rho|log2 r\b|matched)', re.I)
PTR = re.compile(r'\b(WC[1-8]|W\d{1,2}\.\d|memory_beside\w*|rt4_expectation_table|c8_memory_restatements|memory columns?)\b')
EXCL = {'2.0', '3.0', '2.376', '2.807', '0.886', '1.6986', '0.5', '4.0', '1.0', '0.01', '0.1', '0.05'}
MEMWORD = re.compile(r'(macaulay rows|macaulay-row|relation store|dense entries|rows 2\^|memory)', re.I)
def walk(o, path, parent):
    if isinstance(o, dict):
        for k, v in o.items(): yield from walk(v, path + [str(k)], o)
    elif isinstance(o, list):
        for i, v in enumerate(o): yield from walk(v, path + [f'[{v["id"]}]' if isinstance(v, dict) and 'id' in v else f'[{i}]'], o)
    elif isinstance(o, str): yield path, o, parent
def memtoks(s):
    return [m.start() for m in TOK.finditer(s) if MEMLEFT.search(s[max(0, m.start()-40):m.start()])]
def sib_has_mem(parent, own):
    if not isinstance(parent, dict): return False
    return any(isinstance(v, str) and v is not own and (memtoks(v) or MEMWORD.search(v)) for v in parent.values())
def scan(which):
    d = yaml.safe_load(open(F[which])); prior = open(PRIOR[which]).read() if which in PRIOR else None
    raw = open(F[which], 'rb').read(); v1len = 28166 if which == 'hyp' else 0
    v1text = raw[:v1len].decode() if v1len else ''
    out = []
    for path, s, parent in walk(d, [], None):
        mt_all = list(TOK.finditer(s)); mems = memtoks(s)
        for m in mt_all:
            tok = m.group(0)
            if m.group(1) and m.group(1).lstrip('+-\u2212') in EXCL: continue
            if m.start() in mems: continue
            ctx = s[max(0, m.start()-60):m.end()+40]
            if not TIMECTX.search(ctx) and not RHOCTX.search(ctx): continue
            local = s[max(0, m.start()-45):m.end()+10]
            cat = 'rho/group-order' if RHOCTX.search(local) and not re.search(r'(margin|c_i|cost|stage|move)', local, re.I) else 'IC-time'
            if cat == 'IC-time':
                if any(abs(m.start() - p) <= 400 for p in mems) or (MEMWORD.search(s) and len(s) < 400): mark = 'WITH'
                elif sib_has_mem(parent, s): mark = 'BY-SIBLING'
